CREATE TABLE "User" (id UUID PRIMARY KEY,"telegramId" TEXT NOT NULL UNIQUE,username TEXT,"firstName" TEXT NOT NULL,locale TEXT NOT NULL DEFAULT 'en',role TEXT NOT NULL DEFAULT 'USER',banned BOOLEAN NOT NULL DEFAULT false,"isTest" BOOLEAN NOT NULL DEFAULT false,notifications BOOLEAN NOT NULL DEFAULT false,"termsVersion" TEXT,"termsAt" TIMESTAMP(3),"premiumUntil" TIMESTAMP(3),"lastActive" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "User_lastActive_idx" ON "User"("lastActive");
CREATE TABLE "Profile" ("userId" UUID PRIMARY KEY REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,"displayName" TEXT NOT NULL,"birthDate" DATE NOT NULL,gender TEXT NOT NULL,"interestedIn" TEXT[] NOT NULL,bio TEXT NOT NULL DEFAULT '',city TEXT NOT NULL,country TEXT NOT NULL,languages TEXT[] NOT NULL,interests TEXT[] NOT NULL,goal TEXT NOT NULL DEFAULT 'DATING',visible BOOLEAN NOT NULL DEFAULT true,"minAge" INTEGER NOT NULL DEFAULT 18,"maxAge" INTEGER NOT NULL DEFAULT 60,"maxDistance" INTEGER NOT NULL DEFAULT 500,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,"filterLanguages" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"filterInterests" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"filterGoal" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Profile_visible_gender_idx" ON "Profile"(visible,gender);
CREATE TABLE "Session" (id UUID PRIMARY KEY,"userId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,"tokenHash" TEXT NOT NULL UNIQUE,csrf TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE TABLE "AuthReplay" (hash TEXT PRIMARY KEY,"browserHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Photo" (id UUID PRIMARY KEY,"userId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,path TEXT NOT NULL UNIQUE,position INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'PENDING',purpose TEXT NOT NULL DEFAULT 'PROFILE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Photo_userId_purpose_position_idx" ON "Photo"("userId",purpose,position);
CREATE TABLE "Swipe" ("fromId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,"toId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,kind TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("fromId","toId"));
CREATE INDEX "Swipe_toId_kind_idx" ON "Swipe"("toId",kind);
CREATE TABLE "Conversation" (id UUID PRIMARY KEY,"aId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,"bId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,active BOOLEAN NOT NULL DEFAULT true,"startedBy" UUID,"startedAt" TIMESTAMP(3),"readAAt" TIMESTAMP(3),"readBAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("aId","bId"));
CREATE INDEX "Conversation_bId_active_idx" ON "Conversation"("bId",active);
CREATE TABLE "Message" (id UUID PRIMARY KEY,"conversationId" UUID NOT NULL REFERENCES "Conversation"(id) ON DELETE CASCADE ON UPDATE CASCADE,"senderId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,body TEXT NOT NULL,"photoId" UUID,"clientId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("senderId","clientId"));
CREATE INDEX "Message_conversationId_createdAt_id_idx" ON "Message"("conversationId","createdAt",id);
CREATE TABLE "DailyUsage" ("userId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,day TEXT NOT NULL,starts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("userId",day));
CREATE TABLE "Block" ("fromId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,"toId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("fromId","toId"));
CREATE TABLE "Report" (id UUID PRIMARY KEY,"fromId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,"toId" UUID NOT NULL REFERENCES "User"(id) ON DELETE CASCADE ON UPDATE CASCADE,reason TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'OPEN',"adminNote" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Report_status_createdAt_idx" ON "Report"(status,"createdAt");
CREATE TABLE "Plan" (id TEXT PRIMARY KEY,stars INTEGER NOT NULL,days INTEGER NOT NULL,active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "PaymentIntent" (id UUID PRIMARY KEY,"userId" UUID REFERENCES "User"(id) ON DELETE SET NULL ON UPDATE CASCADE,"planId" TEXT NOT NULL REFERENCES "Plan"(id) ON UPDATE CASCADE,stars INTEGER NOT NULL,days INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',"chargeId" TEXT UNIQUE,"invoiceUrl" TEXT,"expiresAt" TIMESTAMP(3) NOT NULL,"paidAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PaymentIntent_userId_createdAt_idx" ON "PaymentIntent"("userId","createdAt");
CREATE TABLE "Policy" (gender TEXT PRIMARY KEY,"dailyStarts" INTEGER NOT NULL,"seeLikes" BOOLEAN NOT NULL);
CREATE TABLE "Content" (key TEXT PRIMARY KEY,value TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AuditLog" (id UUID PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Outbox" (id UUID PRIMARY KEY,kind TEXT NOT NULL,payload JSONB NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,"runAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Outbox_runAt_idx" ON "Outbox"("runAt");
-- Additional invariants Prisma cannot express.
ALTER TABLE "Swipe" ADD CONSTRAINT swipe_not_self CHECK ("fromId"<>"toId"), ADD CONSTRAINT swipe_kind CHECK (kind IN ('LIKE','PASS'));
ALTER TABLE "Conversation" ADD CONSTRAINT ordered_pair CHECK ("aId"<"bId");
ALTER TABLE "Block" ADD CONSTRAINT block_not_self CHECK ("fromId"<>"toId");
ALTER TABLE "Plan" ADD CONSTRAINT positive_plan CHECK (stars>0 AND days>0);
ALTER TABLE "Profile" ADD CONSTRAINT age_range CHECK ("minAge">=18 AND "maxAge">="minAge"), ADD CONSTRAINT profile_gender CHECK (gender IN ('MALE','FEMALE','OTHER'));
-- Application tables must not be accessible through Supabase anon/authenticated roles.
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['User','Profile','Session','AuthReplay','Photo','Swipe','Conversation','Message','DailyUsage','Block','Report','Plan','PaymentIntent','Policy','Content','AuditLog','Outbox'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); END LOOP; END $$;
